"""Verify own medium smoke checkpoint and inspect reference metadata without unpickling."""

import json
import os
import pickletools
import zipfile
from pathlib import Path

import numpy as np
import polars as pl
import torch
from chemprop import featurizers
from chemprop.data import BatchMolGraph
from rdkit import Chem
from train_external_medium import MediumAssayModel

inp, out = Path(os.environ["CYP_INPUT_DIR"]), Path(os.environ["CYP_OUTPUT_DIR"])
# This checkpoint was generated by our preceding recorded smoke run.
checkpoint = torch.load(next(inp.glob("*-best.pt")), map_location="cpu", weights_only=False)
model = MediumAssayModel(len(checkpoint["assays"]), checkpoint["config"]["dropout"])
model.load_state_dict(checkpoint["state_dict"], strict=True)
model.eval()
f = featurizers.SimpleMoleculeMolGraphFeaturizer()
g = BatchMolGraph([f(Chem.MolFromSmiles(s)) for s in ["C", "CCO"]])
with torch.inference_mode():
    h = model.mp(g)
    expected = torch.zeros((2, 600)).index_add_(0, g.batch, h) / 100
    actual = model.embed(g)
    y = model(g)
assert torch.allclose(expected, actual, atol=1e-7, rtol=1e-6)
assert y.shape == (2, len(checkpoint["assays"]) * 2) and torch.isfinite(y).all()
assert model.mp.depth == 4
emb = pl.read_parquet(next(inp.glob("*-external-embeddings.parquet")))
assert emb.height == emb["compound_id"].n_unique() == 6896
assert len(emb.columns) == 601 and np.isfinite(emb.drop("compound_id").to_numpy()).all()
# Reference model metadata is inspected as pickle opcodes; no third-party pickle execution.
reference = next(inp.glob("*-chemprop_medium.pt"))
with zipfile.ZipFile(reference) as z:
    name = next(n for n in z.namelist() if n.endswith("/data.pkl"))
    ops = list(pickletools.genops(z.read(name)))
keys = {
    "depth",
    "d_h",
    "hidden_dim",
    "n_layers",
    "norm",
    "dropout",
    "aggregation",
    "ffn_hidden_dim",
    "ffn_num_layers",
}
windows = []
for i, (_op, arg, pos) in enumerate(ops):
    if isinstance(arg, str) and arg in keys:
        windows.append(
            {
                "key": arg,
                "offset": pos,
                "following": [{"op": o.name, "value": str(a)} for o, a, _ in ops[i + 1 : i + 10]],
            }
        )
(out / "reference-metadata-opcodes.json").write_text(json.dumps(windows, indent=2))
summary = dict(
    checkpoint_strict_load=True,
    mp_depth=model.mp.depth,
    width=model.mp.output_dim,
    norm100_numeric_check=True,
    hidden_linear_layers=3,
    output_shape=list(y.shape),
    exported_rows=emb.height,
    exported_features=len(emb.columns) - 1,
    state_keys=list(checkpoint["state_dict"]),
    reference_inspection="Static pickle opcodes only",
    scope="Architecture and checkpoint smoke; no full training and no comparative score",
)
(out / "summary.json").write_text(json.dumps(summary, indent=2))
print(json.dumps(summary), flush=True)
